import configparser, json, subprocess, urllib.parse, urllib.request

def dexec(container, *args):
    return subprocess.check_output(["docker", "exec", container, *args], text=True)

def get_json(url, headers=None):
    req = urllib.request.Request(url, headers=headers or {})
    with urllib.request.urlopen(req, timeout=20) as response:
        return json.load(response)

sab_cfg = configparser.ConfigParser(interpolation=None)
sab_cfg.read_string(dexec("sabnzbd", "cat", "/config/sabnzbd.ini"))
sab_key = sab_cfg["misc"]["api_key"]

def sab(mode, **params):
    query = {"mode": mode, "output": "json", "apikey": sab_key}
    query.update(params)
    return get_json("http://172.20.1.20:8080/api?" + urllib.parse.urlencode(query))

lid_xml = dexec("lidarr", "cat", "/config/config.xml")
import re
lid_key = re.search(r"<ApiKey>([^<]+)</ApiKey>", lid_xml).group(1)
lid_headers = {"X-Api-Key": lid_key}

